package org.joda.time.chrono;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import org.joda.time.Chronology;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DurationField;
import org.joda.time.IllegalFieldValueException;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.field.BaseDateTimeField;
import org.joda.time.field.DecoratedDurationField;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class GJChronology_getInstance_TriageGen1Test {

    @Test
    public void testGetInstance_NullCutover_UTC() {
        // Tests the branch where gregorianCutover is null and zone is UTC
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, null, 4);
        assertNotNull(chrono);
        assertEquals(DateTimeZone.UTC, chrono.getZone());
        assertEquals(4, chrono.getMinimumDaysInFirstWeek());
    }

    @Test
    public void testGetInstance_WithCutover_UTC() {
        // Tests the branch where gregorianCutover is provided and zone is UTC
        Instant cutover = new Instant(new org.joda.time.LocalDate(2000, 1, 1).toDateTime(DateTimeZone.UTC).getMillis());
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, cutover, 7);
        assertNotNull(chrono);
        assertEquals(cutover, chrono.getGregorianCutover());
        assertEquals(7, chrono.getMinimumDaysInFirstWeek());
    }

    @Test
    public void testGetInstance_WithCutover_NonUTC() {
        // Tests the branch where zone is not UTC (triggers ZonedChronology path)
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        Instant cutover = new Instant(new org.joda.time.LocalDate(2000, 1, 1).toDateTime(zone).getMillis());
        GJChronology chrono = GJChronology.getInstance(zone, cutover, 4);
        assertNotNull(chrono);
        assertEquals(zone, chrono.getZone());
        assertEquals(cutover, chrono.getGregorianCutover());
    }

    @Test
    public void testGetInstance_CacheHit() {
        // Tests the branch where an existing chronology is found in the cache
        DateTimeZone zone = DateTimeZone.UTC;
        int minDays = 4;

        // First call to populate cache
        GJChronology chrono1 = GJChronology.getInstance(zone, null, minDays);

        // Second call with same parameters should return the cached instance
        GJChronology chrono2 = GJChronology.getInstance(zone, null, minDays);

        assertSame("Should return the cached instance", chrono1, chrono2);
    }

    @Test
    public void testGetInstance_CacheMiss_DifferentParams() {
        // Tests that different minDaysInFirstWeek results in a new instance (not a cache hit)
        DateTimeZone zone = DateTimeZone.UTC;

        GJChronology chrono1 = GJChronology.getInstance(zone, null, 4);
        GJChronology chrono2 = GJChronology.getInstance(zone, null, 7);

        assertNotSame(chrono1, chrono2);
        assertEquals(4, chrono1.getMinimumDaysInFirstWeek());
        assertEquals(7, chrono2.getMinimumDaysInFirstWeek());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetInstance_CutoverTooEarly_ThrowsException() {
        // Tests the exception branch: cutoverDate.getYear() <= 0
        // Using a year of 0 or negative via Instant
        Instant tooEarly = new Instant(new org.joda.time.LocalDate(-1, 1, 1).toDateTime(DateTimeZone.UTC).getMillis());
        GJChronology.getInstance(DateTimeZone.UTC, tooEarly, 4);
    }

    @Test
    public void testGetInstance_WithSpecificReadableInstant() {
        // Tests using a custom implementation of ReadableInstant
        ReadableInstant customInstant = new ReadableInstant() {
            @Override
            public long getMillis() {
                return new org.joda.time.LocalDate(1900, 1, 1).toDateTime(DateTimeZone.UTC).getMillis();
            }
        };

        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, customInstant, 4);
        assertNotNull(chrono);
        assertEquals(customInstant.getMillis(), chrono.getGregorianCutover().getMillis());
    }
}
